package com.primehr.learningdevelopment;
import com.primehr.learningdevelopment.participation.domain.*;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.*;import static org.assertj.core.api.Assertions.*;
class LdParticipationDomainTest{
 @Test void nominationRequiresOrderedApprovalLifecycle(){LdNomination n=nomination(1L,"EMP-1");n.submit("EMP-1",Instant.now());n.recommend();n.approve("APR-1",Instant.now());assertThat(n.getStatus()).isEqualTo(LdNomination.Status.APPROVED);assertThatThrownBy(n::cancel).isInstanceOf(IllegalStateException.class);}
 @Test void enrollmentSeparatesInvitationConfirmationAndSubstitution(){LdEnrollment invited=new LdEnrollment("A","N1","O1",1,"of",1L,"EMP-1","Employee 1",11L,"ef1");invited.confirm(Instant.now());assertThat(invited.getStatus()).isEqualTo(LdEnrollment.Status.CONFIRMED);LdEnrollment replacement=new LdEnrollment("A","N2","O1",1,"of",2L,"EMP-2","Employee 2",12L,"ef2");invited.substituteWith(replacement,"Authorized replacement",Instant.now());assertThat(invited.getStatus()).isEqualTo(LdEnrollment.Status.SUBSTITUTED);assertThat(replacement.getStatus()).isEqualTo(LdEnrollment.Status.INVITED);}
 @Test void substitutionRejectsUnapprovedEnrollmentState(){LdEnrollment invited=new LdEnrollment("A","N1","O1",1,"of",1L,"EMP-1","Employee 1",11L,"ef1");LdEnrollment replacement=new LdEnrollment("A","N2","O1",1,"of",2L,"EMP-2","Employee 2",12L,"ef2");replacement.decline("Declined",Instant.now());assertThatThrownBy(()->invited.substituteWith(replacement,"Replace",Instant.now())).isInstanceOf(IllegalArgumentException.class);}
 private LdNomination nomination(Long id,String no){return new LdNomination("A","O1",1,"of","Offering",OffsetDateTime.parse("2027-05-10T08:00:00+08:00"),OffsetDateTime.parse("2027-05-10T17:00:00+08:00"),LdNomination.SourceType.JUSTIFIED,null,null,null,"Agency priority",id,no,"Employee",11L,"ef",41L,"Unit",51L,"Area","org",BigDecimal.ZERO,LdNomination.InitiatorType.EMPLOYEE,no);}
}
